// A1-3 BitLocker read-only volume regression.
//
// Corpus: testdata/bitlocker-golden/{cases.tsv,sectors.tsv,*.bin}, generated by
// an independent pure-Python AES / hashlib oracle. sectors.tsv holds FNV-1a64
// fingerprints of the DECRYPTED logical volume, so every read exercises the
// whole chain: FVE volume header -> best of 3 metadata copies -> VMK protector
// -> AES-CCM unwrap -> FVEK -> AES-XTS/CBC sector decryption -> volume header
// relocation / metadata-area zero fill.
//
// Zero GUI / zero device I/O / zero writes: all sources are in-memory.

#include "../disk/BitLockerVolume.h"

#include <cctype>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

using namespace phoenix;

static int g_fail = 0;
static int g_checks = 0;

#define CHECK(cond, what)                                                        \
    do {                                                                         \
        ++g_checks;                                                              \
        if (!(cond)) {                                                           \
            std::printf("FAIL line %d: %s\n", __LINE__, (what));                 \
            ++g_fail;                                                            \
        }                                                                        \
    } while (0)

static std::vector<std::string> SplitTabs(const std::string& line)
{
    std::vector<std::string> out;
    std::string cur;
    std::istringstream is(line);
    while (std::getline(is, cur, '\t')) out.push_back(cur);
    return out;
}

static std::vector<std::string> ReadLines(const std::string& path)
{
    std::vector<std::string> out;
    std::ifstream f(path);
    std::string line;
    while (std::getline(f, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (!line.empty() && line[0] != '#') out.push_back(line);
    }
    return out;
}

static std::vector<uint8_t> ReadBinary(const std::string& path)
{
    std::ifstream f(path, std::ios::binary);
    return std::vector<uint8_t>((std::istreambuf_iterator<char>(f)),
                                std::istreambuf_iterator<char>());
}

static std::vector<uint8_t> FromHex(const std::string& h)
{
    std::vector<uint8_t> out;
    if ((h.size() & 1u) != 0) return out;
    auto nibble = [](char c) -> int {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    };
    for (size_t i = 0; i < h.size(); i += 2) {
        const int a = nibble(h[i]);
        const int b = nibble(h[i + 1]);
        if (a < 0 || b < 0) return {};
        out.push_back(static_cast<uint8_t>((a << 4) | b));
    }
    return out;
}

static uint64_t Fnv1a64(const uint8_t* p, size_t n)
{
    uint64_t h = 0xcbf29ce484222325ull;
    for (size_t i = 0; i < n; ++i) {
        h ^= p[i];
        h *= 0x100000001b3ull;
    }
    return h;
}

static std::string FnvHex(const uint8_t* p, size_t n)
{
    char buf[32];
    std::snprintf(buf, sizeof(buf), "%016llx", static_cast<unsigned long long>(Fnv1a64(p, n)));
    return std::string(buf);
}

static std::string ResolveGoldenDir()
{
    std::vector<std::string> candidates;
    if (const char* env = std::getenv("PHOENIX_BITLOCKER_GOLDEN_DIR")) {
        if (*env) candidates.emplace_back(env);
    }
    candidates.emplace_back("testdata/bitlocker-golden/");
    candidates.emplace_back("../testdata/bitlocker-golden/");
    candidates.emplace_back("../../testdata/bitlocker-golden/");
    candidates.emplace_back("../../../testdata/bitlocker-golden/");
    candidates.emplace_back("../../../../testdata/bitlocker-golden/");
    for (std::string d : candidates) {
        if (d.empty()) continue;
        if (d.back() != '/' && d.back() != '\\') d += '/';
        if (std::ifstream(d + "cases.tsv").good()) return d;
    }
    return "testdata/bitlocker-golden/";
}

static BitLockerUnlockResult UnlockCase(BitLockerVolume& vol,
                                        const std::string& kind,
                                        const std::string& credential)
{
    if (kind == "clear")   return vol.UnlockWithClearKey();
    if (kind == "recovery") return vol.UnlockWithRecoveryPassword(credential);
    if (kind == "password") return vol.UnlockWithPassword(
        std::wstring(credential.begin(), credential.end()));
    if (kind == "bek") {
        const auto key = FromHex(credential);
        if (key.size() != 32) return BitLockerUnlockResult::BadKeyMaterial;
        return vol.UnlockWithExternalKey(key.data());
    }
    return BitLockerUnlockResult::BadKeyMaterial;
}

struct SectorExpectation
{
    uint64_t offset;
    size_t   length;
    std::string fingerprint;
    std::string note;
};

int main()
{
    const std::string dir = ResolveGoldenDir();
    std::printf("BitLockerVolume golden dir: %s\n", dir.c_str());

    const auto caseLines = ReadLines(dir + "cases.tsv");
    const auto sectorLines = ReadLines(dir + "sectors.tsv");
    CHECK(!caseLines.empty(), "cases.tsv is present");
    CHECK(!sectorLines.empty(), "sectors.tsv is present");

    std::map<std::string, std::vector<SectorExpectation>> expectations;
    for (const auto& line : sectorLines) {
        const auto f = SplitTabs(line);
        if (f.size() < 5) { CHECK(false, "sectors.tsv column count"); continue; }
        expectations[f[0]].push_back({
            std::strtoull(f[1].c_str(), nullptr, 10),
            static_cast<size_t>(std::strtoull(f[2].c_str(), nullptr, 10)),
            f[3], f[4] });
    }

    int okVolumes = 0, totalFingerprints = 0;
    for (const auto& line : caseLines) {
        const auto f = SplitTabs(line);
        if (f.size() < 12) { CHECK(false, "cases.tsv column count"); continue; }
        const std::string& name = f[0];
        const std::string& file = f[1];
        const uint32_t method = static_cast<uint32_t>(std::strtoul(f[2].c_str(), nullptr, 0));
        const std::string& protector = f[3];
        const std::string& credential = f[4];
        const std::string& openExpect = f[5];
        const std::string& unlockExpect = f[6];
        const size_t protectorCount = static_cast<size_t>(std::strtoull(f[7].c_str(), nullptr, 10));
        const uint64_t volumeSize = std::strtoull(f[8].c_str(), nullptr, 10);
        const uint64_t headerOffset = std::strtoull(f[9].c_str(), nullptr, 10);
        const uint64_t headerSize = std::strtoull(f[10].c_str(), nullptr, 10);
        const uint32_t sectorSize = static_cast<uint32_t>(std::strtoul(f[11].c_str(), nullptr, 10));

        const std::vector<uint8_t> source = ReadBinary(dir + file);
        CHECK(source.size() == volumeSize, (name + ": corpus file size").c_str());
        if (source.size() != volumeSize) continue;

        MemoryVirtualDiskReader reader(source);
        BitLockerVolume vol(reader);
        const auto openResult = vol.Open();
        CHECK(std::string(bitlocker_detail::OpenResultName(openResult)) == openExpect,
              (name + ": Open() result").c_str());
        if (openExpect != "Ok") {
            CHECK(!vol.IsUnlocked(), (name + ": rejected volume stays locked").c_str());
            CHECK(!vol.LastError().empty(), (name + ": rejection has a reason").c_str());
            continue;
        }
        CHECK(vol.IsOpen(), (name + ": IsOpen()").c_str());
        CHECK(vol.Info().cipherMethod == method, (name + ": cipher method").c_str());
        CHECK(vol.Info().protectors.size() == protectorCount,
              (name + ": protector enumeration").c_str());
        CHECK(vol.Info().volumeSize == volumeSize, (name + ": volume size").c_str());
        CHECK(vol.Info().volumeHeaderOffset == headerOffset,
              (name + ": volume header relocation offset").c_str());
        CHECK(vol.Info().volumeHeaderSize == headerSize,
              (name + ": volume header relocation size").c_str());
        CHECK(vol.Info().bytesPerSector == sectorSize, (name + ": sector size").c_str());
        CHECK(vol.Info().encryptedVolumeSize == volumeSize,
              (name + ": encrypted volume size").c_str());
        CHECK(vol.Info().metadataAreaSize == 0x1000,
              (name + ": derived metadata area size").c_str());
        CHECK(vol.Info().volumeGuid[0] != 0 || vol.Info().volumeGuid[15] != 0,
              (name + ": volume GUID parsed").c_str());
        CHECK(!vol.Info().cipherName.empty(), (name + ": cipher name").c_str());
        CHECK(vol.Size() == volumeSize, (name + ": IVirtualDiskReader::Size()").c_str());

        const auto unlockResult = UnlockCase(vol, protector, credential);
        CHECK(std::string(bitlocker_detail::UnlockResultName(unlockResult)) == unlockExpect,
              (name + ": unlock result").c_str());
        if (unlockExpect != "Ok") {
            CHECK(!vol.IsUnlocked(), (name + ": failed unlock stays locked").c_str());
            CHECK(!vol.LastError().empty(), (name + ": unlock failure has a reason").c_str());
            uint8_t probe[16] = {};
            CHECK(!vol.Read(0, probe, sizeof(probe)),
                  (name + ": locked volume refuses reads").c_str());
            continue;
        }

        ++okVolumes;
        CHECK(vol.IsUnlocked(), (name + ": IsUnlocked()").c_str());
        CHECK(vol.Info().fvekKeyDataBytes >= 32, (name + ": FVEK key material").c_str());

        const auto& rows = expectations[name];
        CHECK(!rows.empty(), (name + ": has sector expectations").c_str());
        for (const auto& row : rows) {
            ++totalFingerprints;
            std::vector<uint8_t> buf(row.length, 0xa5);
            const bool ok = vol.Read(row.offset, buf.data(), buf.size());
            if (!ok) {
                CHECK(false, (name + ": Read() at " + std::to_string(row.offset)).c_str());
                continue;
            }
            CHECK(FnvHex(buf.data(), buf.size()) == row.fingerprint,
                  (name + ": " + row.note).c_str());
        }

        // Boundary policy: never fabricate bytes past the logical volume.
        std::vector<uint8_t> probe(8, 0);
        CHECK(!vol.Read(volumeSize - 1, probe.data(), 2), (name + ": read past EOF").c_str());
        CHECK(!vol.Read(volumeSize, probe.data(), 1), (name + ": read at EOF").c_str());
        CHECK(vol.Read(0, probe.data(), 0), (name + ": zero-length read").c_str());

        // The decrypted view is anchored to the relocated original boot sector.
        uint8_t boot[512] = {};
        CHECK(vol.ReadDecryptedSector(0, boot), (name + ": ReadDecryptedSector(0)").c_str());
        CHECK(boot[0] == 0xeb && boot[1] == 0x52 && boot[2] == 0x90 &&
              std::memcmp(boot + 3, "NTFS    ", 8) == 0 && boot[510] == 0x55 &&
              boot[511] == 0xaa,
              (name + ": NTFS boot anchor survived relocation").c_str());

        // Wrong credential must never unlock (CCM tag is the authority).
        {
            MemoryVirtualDiskReader reader2(source);
            BitLockerVolume vol2(reader2);
            CHECK(vol2.Open() == BitLockerOpenResult::Ok, (name + ": reopen").c_str());
            std::string badKind = protector;
            std::string badCredential;
            if (protector == "recovery")
                badCredential = "011000-022033-033077-044121-055187-066253-077341-088429";
            else if (protector == "password")
                badCredential = "definitely-not-the-password";
            else if (protector == "bek")
                badCredential = std::string(64, '0');
            else {
                badKind = "bek";
                badCredential = std::string(64, '0');
            }
            if (name == "cbc256_recovery")
                badCredential = "471207-278498-422125-177177-561902-537405-468006-693451";
            const auto bad = UnlockCase(vol2, badKind, badCredential);
            CHECK(bad != BitLockerUnlockResult::Ok,
                  (name + ": wrong credential rejected").c_str());
            CHECK(!vol2.IsUnlocked(), (name + ": wrong credential leaves volume locked").c_str());
        }

        // Negative evidence: flipping one ciphertext byte must change the
        // decrypted result (guards against a fake/constant implementation).
        // Limited to non-stretch protectors to keep the 0x100000-iteration
        // derivation out of this repeated check.
        if (protector == "clear" || protector == "bek") {
            auto tampered = source;
            const uint64_t victim = 0x10000;   // a normally encrypted sector
            tampered[static_cast<size_t>(victim) + 7] ^= 0x01;
            MemoryVirtualDiskReader reader3(std::move(tampered));
            BitLockerVolume vol3(reader3);
            if (vol3.Open() == BitLockerOpenResult::Ok) {
                const auto r3 = UnlockCase(vol3, protector, credential);
                if (r3 == BitLockerUnlockResult::Ok) {
                    std::vector<uint8_t> a(512), b(512);
                    CHECK(vol.Read(victim, a.data(), a.size()), (name + ": pristine read").c_str());
                    CHECK(vol3.Read(victim, b.data(), b.size()), (name + ": tampered read").c_str());
                    CHECK(a != b, (name + ": ciphertext tamper changes plaintext").c_str());
                }
            }
        }

        // Composition: a decrypted BitLocker volume is a valid virtual disk
        // source, so it can feed VirtualDiskSource / VirtualRaid unchanged.
        {
            VirtualDiskSource vds(vol);
            CHECK(vds.Open() == VirtualDiskOpenResult::Ok,
                  (name + ": VirtualDiskSource on decrypted volume").c_str());
            CHECK(vds.Format() == VirtualDiskFormat::Raw,
                  (name + ": decrypted volume looks like a raw disk").c_str());
            uint8_t s[512] = {};
            CHECK(vds.ReadSectors(0, 1, s),
                  (name + ": VirtualDiskSource::ReadSectors").c_str());
            CHECK(std::memcmp(s, boot, 512) == 0,
                  (name + ": composed read equals direct decrypted read").c_str());
        }

        // Strict read-only: opening / unlocking / reading never touched the source.
        CHECK(reader.Data() == source, (name + ": source volume unchanged (S1)").c_str());

        vol.ClearKeys();
        CHECK(!vol.IsUnlocked(), (name + ": ClearKeys locks the volume").c_str());
        std::vector<uint8_t> after(16, 0);
        CHECK(!vol.Read(0, after.data(), after.size()),
              (name + ": cleared keys refuse reads").c_str());
    }

    // Robustness: all three metadata copies destroyed -> explicit failure,
    // never a silent fall-through to a raw-disk scan.
    {
        const std::vector<uint8_t> source = ReadBinary(dir + "xts128_clear.bin");
        CHECK(!source.empty(), "robustness corpus available");
        if (!source.empty()) {
            auto broken = source;
            for (uint64_t off : { 0x30000ull, 0x31000ull, 0x32000ull })
                broken[static_cast<size_t>(off)] = 0x00;
            MemoryVirtualDiskReader reader(std::move(broken));
            BitLockerVolume vol(reader);
            CHECK(vol.Open() == BitLockerOpenResult::NoUsableMetadata,
                  "destroyed metadata copies -> NoUsableMetadata");
            CHECK(!vol.IsUnlocked(), "no metadata -> remains locked");
        }
    }

    // Empty / truncated sources are rejected.
    {
        MemoryVirtualDiskReader tiny(std::vector<uint8_t>(64, 0));
        BitLockerVolume vol(tiny);
        CHECK(vol.Open() == BitLockerOpenResult::TooSmall, "tiny source -> TooSmall");
    }

    CHECK(okVolumes == 6, "six decryptable volumes verified");
    CHECK(totalFingerprints >= 90, "golden fingerprint coverage");

    std::printf("BitLockerVolume: %d checks, %d failure(s), %d volumes, %d fingerprints\n",
                g_checks, g_fail, okVolumes, totalFingerprints);
    if (g_fail != 0)
        std::printf("  corpus missing? run: python testdata/tools/Gen-BitLockerGolden.py\n");
    return g_fail == 0 ? 0 : 1;
}
